292				font-size: 0.875rem;
293				color: var(--text-secondary);
294			}
295			input:user-invalid,
296			textarea:user-invalid {
297				border-color: #c62828;
298				border-width: 2px;
299			}
300			[aria-invalid="true"] {
301				border-color: #c62828;
302				border-width: 2px;
303			}
304			.error-message {
305				display: block;
306				color: #c62828;
307				font-size: 0.875rem;
308				margin-top: 0.25rem;
309			}
310			.live-region {
311				display: flex;
312				align-items: center;
313				min-height: 3.5rem;
