327					color-scheme: light;
328					--text: #000;
329					--text-secondary: #333;
330					--background: #fff;
331					--surface: #fff;
332					--accent: #000;
333					--border: #999;
334				}
335				.skip-link,
336				button,
337				.button {
338					display: none;
339				}
340				body {
341					display: block;
342					min-height: 0;
343					max-width: none;
344					padding: 0;
345				}
346				a {
347					color: inherit;
348					text-decoration: underline;
349				}
